from pathlib import Path
import hashlib, json
root = Path('products/services/sqlite-repair/bespoke-inbound')
for path in sorted(root.glob('*')):
    if not path.is_file():
        continue
    name = path.name.lower()
    if 'quote' not in name and 'terms' not in name:
        continue
    data = path.read_bytes()
    print(json.dumps({'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}, ensure_ascii=False))
    if len(data) <= 16000:
        print(data.decode('utf-8'))
